import os,glob,re,json
def load():
    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load(); print(sorted(G))
from collections import Counter
c=Counter(v for r in G['Test input'] for v in r); print(c)
def f(g):
    H=len(g); W=len(g[0]); bg=c
    # background = most common
    cnt=Counter(v for r in g for v in r); bg=cnt.most_common(1)[0][0]
    seen=[[False]*W for _ in range(H)]
    out=[r[:] for r in g]
    for i in range(H):
        for j in range(W):
            if g[i][j]!=bg and not seen[i][j]:
                col=g[i][j]; st=[i]; comp=[]
                while st:
                    y,x=st.pop()
                    if seen[y][x]: continue
                    seen[y][x]=True; comp.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and g[ny][nx]==col and not seen[ny][nx]: st.append((ny,nx))
                ys=[p[0] for p in comp]; xs=[p[1] for p in comp]
                for y,x in comp:
                    if y in (min(ys),max(ys)) or x in (min(xs),max(xs)): out[y][x]=col
                    else: out[y][x]=8
    return out
print(f(G['Demo pair 1 input'])==G['Demo pair 1 output'])

